}

    if ($mapping.ContainsKey($testId)) { $testId = $mapping[$testId] }
    if ($testId -notmatch '^ORCA\.\d{1,3}(\.\d+)?$') {
        throw "Test ID '$testId' is not in the Maester format (ORCA.nnn or ORCA.nnn.n). Add a mapping for it in Update-OrcaTests.ps1."
    }

    # Attribute values (test attribute design, section 2). Every ORCA check is a Defender for Office 365
    # setting; the other classification values come from orca-test-metadata.json.
    $meta = $metadata[$testId]
    if (-not $meta) {
        Write-Warning "$testId has no entry in orca-test-metadata.json; using Severity Medium and Author merill. Add an entry and regenerate."
        $meta = @{ Severity = 'Medium'; Author = @('merill') }
    }
    $services = @('ExchangeOnline')
    $readsScc = @($sccKeys | Where-Object { $check.Content -match "\[[`"']$_[`"']\]|ContainsKey\([`"']$_[`"']\)" })
    if ($readsScc.Count -gt 0) { $services += 'SecurityCompliance' }

    $attribute = [System.Collections.Generic.List[string]]::new()
    $attribute.Add("Id = $(Format-OrcaString $testId)")
    $attribute.Add("Title = $(Format-OrcaString $title)")
    $attribute.Add("Product = 'defender'")
    if ($meta.RelatedProduct) { $attribute.Add("RelatedProduct = $(Format-OrcaList @($meta.RelatedProduct))") }
    foreach ($name in 'Feature', 'Area', 'ResourceType') {
        if ($meta[$name]) { $attribute.Add("$name = $(Format-OrcaString $meta[$name])") }
    }
    $attribute.Add("Severity = $(Format-OrcaString $meta.Severity)")
    foreach ($name in 'UserImpact', 'ImplementationCost') {
        if ($meta[$name]) { $attribute.Add("$name = $(Format-OrcaString $meta[$name])") }
    }
    if ($meta.Mitre) { $attribute.Add("Mitre = $(Format-OrcaList @($meta.Mitre))") }
    if ($meta.Control) { $attribute.Add("Control = $(Format-OrcaList @($meta.Control))") }
    $attribute.Add("Service = $(Format-OrcaList $services)")
    # Defender for Office 365 Plan 1 or 2. ORCA detects MDO itself and reports 'not completed' without it.
    if ($check.Services -eq 'MDO') { $attribute.Add("License = 'ATP_ENTERPRISE'") }
    $attribute.Add("Author = $(Format-OrcaList @($meta.Author))")
    if ($meta.Contributor) { $attribute.Add("Contributor = $(Format-OrcaList @($meta.Contributor))") }
    $attributeText = ($attribute | ForEach-Object { "        $_" }) -join ",`n"

    $testScript = @"
# Generated by ./build/orca/Update-OrcaTests.ps1 from powershell/internal/generated/orca/$($check.File). Do not edit.

function Test-$func {
    <#
    .SYNOPSIS
    $title

    .DESCRIPTION
    Runs the ORCA check $func (https://github.com/cammurray/orca) against the Exchange Online configuration.

6:    Without -Offline, clones or updates https://github.com/cammurray/orca in build/orca/orca and
12:    With -Offline, only the native tests are regenerated, from the committed
23:.PARAMETER Offline
36:    ./build/orca/Update-OrcaTests.ps1 -Offline -OutputPath ./out
41:    [Parameter()] [switch] $Offline,
114:if (-not $Offline) {
BeforeAll {
    $script:RepoRoot = (Resolve-Path "$PSScriptRoot/../../..").Path
    $script:Generator = Join-Path $script:RepoRoot 'build/orca/Update-OrcaTests.ps1'
    $script:CommittedRoot = Join-Path $script:RepoRoot 'tests/orca'
    $script:FreshRoot = Join-Path $TestDrive 'orca'

    # Regenerate the native tests from the committed check-ORCA*.ps1 files, without downloading ORCA.
    $pwsh = (Get-Process -Id $PID).Path
    $script:GeneratorOutput = & $pwsh -NoProfile -NonInteractive -File $script:Generator -Offline -OutputPath $script:FreshRoot 2>&1
    $script:GeneratorExitCode = $LASTEXITCODE

    $script:Committed = @(Get-ChildItem -Path $script:CommittedRoot -File -Filter 'Test.ORCA.*' | Sort-Object Name)
    $script:Fresh = @(Get-ChildItem -Path $script:FreshRoot -File -Filter 'Test.ORCA.*' -ErrorAction SilentlyContinue | Sort-Object Name)
}

Describe 'ORCA generator' {
    It 'runs offline without errors' {
        $script:GeneratorExitCode | Should -Be 0 -Because ($script:GeneratorOutput | Out-String)
    }

    It 'produces the same set of native test files as tests/orca' {
        $script:Fresh.Count | Should -BeGreaterThan 0
        ($script:Fresh.Name -join "`n") | Should -Be ($script:Committed.Name -join "`n")
    }

    It 'produces exactly the committed content of every native test file' {
        $drifted = foreach ($file in $script:Committed) {
            $freshPath = Join-Path $script:FreshRoot $file.Name
            if (-not (Test-Path -LiteralPath $freshPath)) { continue }
            $committed = [System.IO.File]::ReadAllText($file.FullName) -replace "`r`n", "`n"
            $fresh = [System.IO.File]::ReadAllText($freshPath) -replace "`r`n", "`n"
            if ($committed -ne $fresh) { $file.Name }
        }
        @($drifted) | Should -BeNullOrEmpty -Because 'tests/orca is generated; edit build/orca/Update-OrcaTests.ps1 or build/orca/orca-test-metadata.json and run ./build/orca/Update-OrcaTests.ps1 -Offline'
    }

    It 'leaves no 2.x Pester wrappers or exported ORCA check functions' {
        @(Get-ChildItem -Path $script:CommittedRoot -File -Filter '*.Tests.ps1') | Should -BeNullOrEmpty
        Test-Path (Join-Path $script:RepoRoot 'powershell/public/orca') | Should -BeFalse
    }
